insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('HR', 'default', 'Neovisni računski plan po vrsti računa', '{}'::jsonb, true, 'companies', '{}'::text[], null, 'Zakon o računovodstvu (pročišćeni tekst) čl. 8. propisuje samo da poduzetnik vodi poslovne knjige po načelu dvojnog knjigovodstva i sastavlja financijske izvještaje prema Hrvatskim standardima financijskog izvještavanja (HSFI) ili MSFI/MSFI za MSS — ne postoji zakonom propisan računski plan. U praksi je najrašireniji "Računski plan za poduzetnike" koji svake godine objavljuje RRiF (Hrvatska zajednica računovođa i financijskih djelatnika), djelo zaštićeno autorskim pravom čije brojeve računa i nazive ovaj pack ne preuzima. Ovaj plan je samostalan: četveroznamenkasti brojevi čija prva znamenka razlikuje dugotrajnu imovinu (1xxx-0xxx po vrsti), kratkotrajnu imovinu (1xxx), kapital (4xxx), dugoročne obveze i rezerviranja (5xxx), kratkoročne obveze (6xxx), rashode (7xxx) i prihode (8xxx); potonja dva razreda dodatno prate podjelu HSFI 15/MSFI-jevog računa dobiti i gubitka na poslovne, financijske i ostale stavke. Zbog toga financijski izvještaji ovog pack-a padaju na okvir generic (packs/generic/), koji ih izvodi iz osamnaest vrsta računa; hrvatska Bilanca i RDG s AOP oznakama (Pravilnik o strukturi i sadržaju godišnjih financijskih izvještaja) nisu još preslikani red po red — vidi README.md i docs/international.md, odjeljak "From Croatia".', 'zakon-pdv')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

