  ('HR', 'HR-P-ICG-25', 'Stjecanje dobara unutar EU — 25%', '{}'::jsonb, null, 'percent', 25, 'purchase', 'intracom_acquisition_goods', date '2026-01-01', null, 'Zakon o PDV, oporezivanje stjecanja dobara unutar Europske unije — primatelj obračunava PDV po stopi kojom bi dobra bila oporezovana u tuzemstvu, i istovremeno odbija pretporez (čl. 58.-61.).', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
