  ('HR', 'HR-P-IMPORT', 'PDV pri uvozu dobara', '{}'::jsonb, null, 'percent', 25, 'purchase', 'import', date '2026-01-01', null, 'Zakon o PDV čl. 32. st. 1. — oporezivi događaj kod uvoza dobara nastaje u trenutku uvoza; PDV obračunava carinska služba na temelju uvozne deklaracije, a obveznik odbija pretporez (čl. 58.-61.).', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
