values
  ('HR', 'HR-PDV', 'Obrazac PDV — Prijava poreza na dodanu vrijednost', array['month', 'quarter']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Zakon o PDV čl. 84. st. 1. — porezno razdoblje je razdoblje od prvog do posljednjeg dana u kalendarskom mjesecu, za sve porezne obveznike kojima Zakon ne daje pravo na tromjesečno razdoblje. Obrazac je u primjeni od veljače 2026. (uključuje podatke o donacijama hrane).', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Zakon o PDV čl. 85. st. 6., kako je izmijenjen čl. 4. Zakona o izmjenama i dopunama Zakona o porezu na dodanu vrijednost (NN 151/25), na snazi od 1. siječnja 2026. — prijava PDV-a podnosi se do zadnjeg dana u mjesecu koji slijedi po završetku obračunskog razdoblja (do 1. siječnja 2026. rok je bio 20. dan tog mjeseca).', 'zakon-pdv-nn151-25', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

