values
  ('HR', 'HR-PDV', 'I1', 'base', 'Isporuke u RH za koje PDV obračunava primatelj (tuzemni prijenos porezne obveze)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 75. st. 3. t. a) — građevinske usluge; primatelj-obveznik obračunava PDV, isporučitelj iskazuje samo osnovicu.', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I2', 'base', 'Isporuke dobara obavljene u drugim državama članicama', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Uputa za popunjavanje Obrasca PDV — isporuke dobara čije je mjesto oporezivanja u drugoj državi članici (npr. isporuke s ugradnjom ili montažom, prodaja na daljinu iznad praga druge države).', 'eporezna-uputa-pdv'),
  ('HR', 'HR-PDV', 'I3', 'base', 'Isporuke dobara unutar EU', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 41. st. 1. t. a) — isporuka dobara poreznom obvezniku registriranom za potrebe PDV-a u drugoj državi članici je oslobođena PDV-a.', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I4', 'base', 'Obavljene usluge unutar EU', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 17. st. 1. — mjesto obavljanja usluge poreznom obvezniku je mjesto njegova sjedišta; kad je to druga država članica, primatelj obračunava PDV (čl. 75. st. 1. t. 6.).', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I5', 'base', 'Obavljene isporuke osobama bez sjedišta u RH', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Uputa za popunjavanje Obrasca PDV — isporuke dobara i usluga čije je mjesto oporezivanja izvan RH, obavljene osobama bez sjedišta, prebivališta ili uobičajenog boravišta u RH.', 'eporezna-uputa-pdv'),
  ('HR', 'HR-PDV', 'I6', 'base', 'Sastavljanje i postavljanje dobara u drugoj državi članici EU', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Uputa za popunjavanje Obrasca PDV — isporuka dobara s ugradnjom ili montažom u drugoj državi članici, koja se tamo smatra mjestom oporezivanja.', 'eporezna-uputa-pdv'),
  ('HR', 'HR-PDV', 'I7', 'base', 'Isporuke novih prijevoznih sredstava u EU', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 41. st. 1. t. b) — isporuka novog prijevoznog sredstva otpremljenog ili prevezenog u drugu državu članicu je oslobođena PDV-a, i to osobi koja nije registrirana za potrebe PDV-a.', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I8', 'base', 'Tuzemne isporuke (oslobođene bez prava na odbitak pretporeza)', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 40. — tuzemne isporuke oslobođene PDV-a bez prava na odbitak pretporeza (npr. najam stambenih prostorija, čl. 40. st. 1. t. l).', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I9', 'base', 'Izvozne isporuke', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 45. st. 1. t. 1. — izvozna isporuka dobara otpremljenih ili prevezenih izvan Europske unije je oslobođena PDV-a s pravom na odbitak pretporeza.', 'zakon-pdv'),
  ('HR', 'HR-PDV', 'I10', 'base', 'Ostala oslobođenja', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Zakon o PDV čl. 39. — oslobođenja u javnom interesu i druga oslobođenja s pravom na odbitak pretporeza koja ne pripadaju drugom redku ovog obrasca.', 'zakon-pdv'),
