update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Zakon o obveznim odnosima čl. 29. — zatezna kamata u trgovačkim ugovorima: referentna stopa uvećana za 8 postotnih poena, ažurirana polugodišnje (1. siječnja i 1. srpnja) i objavljena u Narodnim novinama.',
  numbering_legal_reference     = 'Zakon o PDV čl. 79. st. 1. t. 3. — račun sadrži broj računa koji ga jednoznačno identificira; obveznici fiskalizacije iskazuju broj u tri dijela (redni broj, oznaka poslovnog prostora, oznaka naplatnog uređaja). Zakon traži jednoznačnost, a ne neprekinutu godišnju numeraciju, otuda sequential i ne gapless_per_year.',
  numbering_source_key          = 'zakon-pdv',
  payment_terms_legal_reference = 'Zakon o rokovima ispunjenja novčanih obveza čl. 4. — kad ugovorom između poduzetnika nije određen rok ispunjenja novčane obveze, dužnik je obvezan ispuniti novčanu obvezu u roku od 30 dana.',
  payment_terms_source_key      = 'zakon-rokovi-placanja',
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Zakon o PDV čl. 30. st. 1. — obveza obračuna PDV-a nastaje u trenutku kada su dobra isporučena ili usluge obavljene. St. 5. — kod predujma, obveza nastaje u trenutku primitka predujma, do visine primljenog iznosa. Ovaj pack ne modelira izdavanje računa kao zamjenu za trenutak isporuke, jer za to u Zakonu o PDV-u — za razliku od Austrije ili Luksemburga — nije pronađena opća odredba.',
  tax_point_source_key          = 'zakon-pdv',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Zakon o računovodstvu čl. 9. st. 4. — poslovni događaj se u poslovnim knjigama iskazuje na temelju vjerodostojne knjigovodstvene isprave; ispravak pogrešno unesenog podatka obavlja se na način da se može utvrditi izvorni sadržaj, pa se knjižena isporuka ispravlja knjigovodstvenom ispravkom (storno knjiženjem ili odobrenjem/terećenjem), a ne izmjenom izvornog zapisa.',
  posted_edit_policy_source_key = 'zakon-pdv',
  einvoice_profile              = 'peppol-bis-3',
  einvoice_mandatory_from       = date '2026-01-01',
  einvoice_obligation           = 'mandatory',
  einvoice_legal_reference      = 'Zakon o fiskalizaciji (NN 89/25) čl. 33.-57., na snazi od 1. siječnja 2026. — svaki obveznik fiskalizacije s poslovnim nastanom u Republici Hrvatskoj mora od tog dana izdavati i zaprimati eRačune u transakcijama s drugim obveznicima fiskalizacije (B2B); tuzemni eRačun se razmjenjuje preko ovlaštenog informacijskog posrednika ili pristupne točke, u formatu UBL 2.1 s hrvatskim CIUS proširenjem HR-EXT nad Peppol BIS Billing 3.0, koji je semantički model EN 16931. mandatory_from nosi datum koji obvezuje sve odjednom — obveza zaprimanja vrijedi od 1. siječnja 2026. i za obveznike PDV-a i za one koji nisu, dok obveza izdavanja za neobveznike PDV-a počinje tek 1. siječnja 2027. i nije ovdje posebno modelirana. Prema Zakonu o elektroničkom izdavanju računa u javnoj nabavi (NN 94/18), obveza zaprimanja eRačuna u javnoj nabavi (B2G) postoji već od 1. prosinca 2018., a obveza izdavanja od 1. srpnja 2019., preko središnje platforme FINA-e; ta starija obveza ne mijenja gornju riječ jer B2B obveza od 2026. postoji za sve. profile imenuje temeljni europski format; hrvatsko CIUS proširenje HR-EXT i sama razmjena preko informacijskog posrednika/FINA-e nisu ovim pack-om modelirani — vidi docs/international.md, odjeljak "From Croatia".',
  einvoice_source_key           = 'zakon-fiskalizacija',
  party_scheme                  = null,
  vat_scheme                    = '9934',
  bank_statement_formats        = array['camt.053']::text[],
  payment_formats               = array['pain.001']::text[],
  fiscal_year_default           = 'calendar'
 where country = 'HR';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('HR', 'reverse_charge', 'reverse_charge', 'Prijenos porezne obveze', '{}'::jsonb, 10, date '1970-01-01', null, 'Zakon o PDV čl. 78. st. 1. — kad je za obračun PDV-a obvezan primatelj dobara ili usluga, umjesto iznosa PDV-a na računu se navodi napomena o prijenosu porezne obveze na primatelja.'),
  ('HR', 'intracom_goods', 'intra_eu_goods', 'Oslobođeno PDV-a — isporuka dobara unutar Europske unije (čl. 41. Zakona o PDV-u)', '{}'::jsonb, 20, date '1970-01-01', null, 'Zakon o PDV čl. 78. st. 1. t. 2. i čl. 41. st. 1. t. a) — isporuka dobara poreznom obvezniku registriranom za potrebe PDV-a u drugoj državi članici je oslobođena, a račun mora sadržavati upućivanje na odredbu na temelju koje je isporuka oslobođena.'),
  ('HR', 'intracom_services', 'intra_eu_services', 'Prijenos porezne obveze — usluga oporeziva u državi sjedišta primatelja (čl. 17. st. 1. Zakona o PDV-u)', '{}'::jsonb, 30, date '1970-01-01', null, 'Zakon o PDV čl. 78. st. 1. t. 2. i čl. 17. st. 1. — mjesto obavljanja usluge poreznom obvezniku je mjesto njegova sjedišta; kad je to druga država članica, primatelj obračunava PDV, a račun upućuje na odredbu na temelju koje se isporuka smatra oslobođenom u tuzemstvu.'),
  ('HR', 'export', 'export', 'Izvozna isporuka oslobođena PDV-a (čl. 45. Zakona o PDV-u)', '{}'::jsonb, 40, date '1970-01-01', null, 'Zakon o PDV čl. 78. st. 1. t. 2. i čl. 45. st. 1. t. 1. — izvozna isporuka dobara je oslobođena PDV-a; račun upućuje na tu odredbu.'),
  ('HR', 'exempt', 'exempt', 'Oslobođeno PDV-a bez prava na odbitak pretporeza', '{}'::jsonb, 50, date '1970-01-01', null, 'Zakon o PDV čl. 78. st. 1. t. 2. — za oslobođenu isporuku račun upućuje na odredbu Zakona o PDV-u, propisa donesenog na temelju njega ili Direktive 2006/112/EZ na temelju koje je isporuka oslobođena.'),
